// Extract lease text from webhook payload
const input = $input.first().json.body;

let leaseText = '';
let leaseId = input.lease_id || null;
let propertyId = input.property_id || null;
let fileName = input.file_name || 'lease_agreement.txt';

if (input.lease_text) {
  // Direct text input
  leaseText = input.lease_text;
} else if (input.pdf_content) {
  // Base64 encoded PDF content
  // In production, use a PDF extraction service
  leaseText = Buffer.from(input.pdf_content, 'base64').toString('utf-8');
} else {
  // Fallback - assume body contains the text directly
  leaseText = JSON.stringify(input);
}

// Validate minimum content
if (!leaseText || leaseText.length < 50) {
  throw new Error('Insufficient lease agreement text provided. Minimum 50 characters required.');
}

return {
  json: {
    lease_id: leaseId,
    property_id: propertyId,
    file_name: fileName,
    lease_text: leaseText,
    text_length: leaseText.length,
    processed_at: new Date().toISOString()
  }
};

// Parse Groq AI response and structure for database
const groqResponse = $input.first().json;
const originalData = $('Code - Extract Lease Text').first().json;

try {
  // Extract the AI analysis from Groq response
  const analysisContent = groqResponse.choices?.[0]?.message?.content;

  if (!analysisContent) {
    throw new Error('No analysis content received from Groq AI');
  }

  // Parse the JSON response
  let analysis;
  try {
    analysis = JSON.parse(analysisContent);
  } catch (e) {
    // Try to extract JSON from markdown code block if present
    const jsonMatch = analysisContent.match(/```json\s*([\s\S]*?)```/) || 
                      analysisContent.match(/```\s*([\s\S]*?)```/) ||
                      analysisContent.match(/({[\s\S]*})/);
    if (jsonMatch) {
      analysis = JSON.parse(jsonMatch[1]);
    } else {
      throw new Error('Could not parse AI response as JSON');
    }
  }

  // Validate required fields
  const validatedAnalysis = {
    parties: analysis.parties || { landlord: '', tenant: '', agent: '' },
    property: analysis.property || { address: '', type: '' },
    financial: analysis.financial || { monthly_rent: 0, deposit: 0, escalation_percent: 0, payment_date: '' },
    duration: analysis.duration || { start_date: '', end_date: '', renewal_terms: '' },
    clauses: analysis.clauses || { pets_allowed: false, maintenance_responsibility: '', subletting_allowed: false, early_termination: '' },
    risk_assessment: analysis.risk_assessment || { level: 'low', concerns: [], missing_clauses: [] },
    compliance: analysis.compliance || { fica_referenced: false, popia_referenced: false, consumer_protection_act: false }
  };

  return {
    json: {
      lease_id: originalData.lease_id,
      property_id: originalData.property_id,
      file_name: originalData.file_name,
      analysis: validatedAnalysis,
      raw_response: analysisContent,
      risk_level: validatedAnalysis.risk_assessment.level,
      analyzed_at: new Date().toISOString()
    }
  };

} catch (error) {
  return {
    json: {
      error: true,
      message: error.message,
      lease_id: originalData.lease_id,
      raw_response: JSON.stringify(groqResponse)
    }
  };
}

// Prepare summary response
const data = $input.first().json;
const analysis = data.analysis;

// Build executive summary
let summary = `## Lease Agreement Analysis\n\n`;
summary += `**Property:** ${analysis.property?.address || 'Not specified'}\n`;
summary += `**Risk Level:** ${analysis.risk_assessment?.level?.toUpperCase() || 'UNKNOWN'}\n\n`;

// Parties
summary += `### Parties\n`;
summary += `- Landlord: ${analysis.parties?.landlord || 'Not specified'}\n`;
summary += `- Tenant: ${analysis.parties?.tenant || 'Not specified'}\n`;
summary += `- Agent: ${analysis.parties?.agent || 'Not specified'}\n\n`;

// Financial
summary += `### Financial Terms\n`;
summary += `- Monthly Rent: R${analysis.financial?.monthly_rent?.toLocaleString() || '0'}\n`;
summary += `- Deposit: R${analysis.financial?.deposit?.toLocaleString() || '0'}\n`;
summary += `- Escalation: ${analysis.financial?.escalation_percent || 0}%\n`;
summary += `- Payment Due: ${analysis.financial?.payment_date || 'Not specified'}\n\n`;

// Duration
summary += `### Lease Duration\n`;
summary += `- Start: ${analysis.duration?.start_date || 'Not specified'}\n`;
summary += `- End: ${analysis.duration?.end_date || 'Not specified'}\n`;
summary += `- Renewal: ${analysis.duration?.renewal_terms || 'Not specified'}\n\n`;

// Key Clauses
summary += `### Key Clauses\n`;
summary += `- Pets Allowed: ${analysis.clauses?.pets_allowed ? 'Yes' : 'No'}\n`;
summary += `- Maintenance: ${analysis.clauses?.maintenance_responsibility || 'Not specified'}\n`;
summary += `- Subletting: ${analysis.clauses?.subletting_allowed ? 'Allowed' : 'Not Allowed'}\n\n`;

// Risk Assessment
if (analysis.risk_assessment?.concerns?.length > 0) {
  summary += `### ⚠️ Risk Concerns\n`;
  analysis.risk_assessment.concerns.forEach(concern => {
    summary += `- ${concern}\n`;
  });
  summary += `\n`;
}

// Missing Clauses
if (analysis.risk_assessment?.missing_clauses?.length > 0) {
  summary += `### ⚠️ Missing Standard Clauses\n`;
  analysis.risk_assessment.missing_clauses.forEach(clause => {
    summary += `- ${clause}\n`;
  });
  summary += `\n`;
}

// Compliance
summary += `### Compliance Check\n`;
summary += `- FICA Referenced: ${analysis.compliance?.fica_referenced ? '✓' : '✗'}\n`;
summary += `- POPIA Referenced: ${analysis.compliance?.popia_referenced ? '✓' : '✗'}\n`;
summary += `- Consumer Protection Act: ${analysis.compliance?.consumer_protection_act ? '✓' : '✗'}\n\n`;

summary += `---\n*Analyzed at: ${data.analyzed_at}*`;

return {
  json: {
    success: true,
    lease_id: data.lease_id,
    property_id: data.property_id,
    risk_level: data.risk_level,
    summary: summary,
    analysis: analysis,
    recommendations: analysis.risk_assessment?.concerns || []
  }
};

// High risk alert notification
const data = $('Code - Parse AI Response').first().json;
const analysis = data.analysis;

const alert = {
  alert_type: 'HIGH_RISK_LEASE',
  lease_id: data.lease_id,
  property_id: data.property_id,
  risk_level: 'HIGH',
  concerns: analysis.risk_assessment?.concerns || [],
  missing_clauses: analysis.risk_assessment?.missing_clauses || [],
  alert_message: `High risk lease agreement detected for ${analysis.property?.address || 'unknown property'}`,
  requires_review: true,
  created_at: new Date().toISOString()
};

return { json: alert };

